<template>
  <div v-title :data-title="title" class="me-archive-body">
    <div class="me-archive-container">

      <aside class="me-archive-sidebar">
        <h3 class="me-sidebar-title">📅 文章归档</h3>
        <ul class="me-month-list">
          <li @click="showAll" class="me-month-item" :class="{ active: !article.query.year }">
            <span>全部</span>
            <span class="me-count">{{totalCount}}</span>
          </li>
          <li v-for="a in archives" :key="a.year + a.month" class="me-month-item" :class="{ active: article.query.year === a.year && article.query.month === a.month }" @click="changeArchive(a.year, a.month)">
            <span>{{a.year}}年{{a.month}}月</span>
            <span class="me-count">{{a.count}}</span>
          </li>
        </ul>
      </aside>


      <main class="me-archive-main">
        <div class="me-month-title">{{currentArchive}}</div>

        <article-scroll-page :query="article.query"></article-scroll-page>

      </main>
    </div>
  </div>

</template>

<script>
  import ArticleScrollPage from '@/views/common/ArticleScrollPage'
  import {listArchives} from '@/api/article'

  export default {
    name: "BlogArchive",
    components: {
      ArticleScrollPage
    },
    created() {
      this.listArchives()
    },
    watch: {
      '$route': {
        handler() {
          if (this.$route.params.year && this.$route.params.month) {
            this.article.query = {
              year: parseInt(this.$route.params.year),
              month: parseInt(this.$route.params.month)
            }
          } else {
            this.article.query = {}
          }
        },
        immediate: true
      }
    },
    data() {
      return {
        article: {
          query: {}
        },
        archives: [],
        totalCount: 0
      }
    },
    computed: {
      title (){
        return '卫星地面融合网络社区-文章归档-' + this.currentArchive
      },
      currentArchive (){
        if(this.article.query.year && this.article.query.month){
          return `${this.article.query.year}年${this.article.query.month}月`
        }
        return '全部'
      }
    },
    methods: {

      changeArchive(year, month) {
        this.$router.push({path: `/archives/${year}/${month}`})
      },
      showAll() {
        this.$router.push({path: '/archives'})
      },
      listArchives() {
        listArchives().then((data => {
          this.archives = data.data
          this.totalCount = this.archives.reduce((sum, item) => sum + item.count, 0)
        })).catch(error => {
          this.$message({type: 'error', message: '文章归档加载失败!', showClose: true})
        })
      }
    }
  }
</script>

<style scoped>
  .me-archive-body {
    margin: 60px auto 140px;
    max-width: 1200px;
    padding: 0 20px;
    width: 100%;
    box-sizing: border-box;
  }

  .me-archive-container {
    display: flex;
    gap: 30px;
  }

  .me-archive-sidebar {
    width: 220px;
    flex-shrink: 0;
    background: #fff;
    border-radius: 8px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
    position: sticky;
    top: 80px;
    height: fit-content;
  }

  .me-sidebar-title {
    font-size: 16px;
    font-weight: bold;
    color: #333;
    margin-bottom: 15px;
    padding-bottom: 10px;
    border-bottom: 1px solid #f0f0f0;
  }

  .me-month-list {
    list-style: none;
    padding: 0;
    margin: 0;
  }

  .me-month-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    color: #666;
    font-size: 14px;
  }

  .me-month-item:hover {
    background: #f5f7fa;
    color: #5FB878;
  }

  .me-month-item.active {
    background: #e8f5ec;
    color: #5FB878;
    font-weight: 500;
  }

  .me-count {
    font-size: 12px;
    background: #f0f0f0;
    color: #999;
    padding: 2px 8px;
    border-radius: 10px;
  }

  .me-month-item.active .me-count {
    background: #5FB878;
    color: #fff;
  }

  .me-archive-main {
    flex: 1;
    min-width: 0;
  }

  .me-month-title {
    font-size: 18px;
    font-weight: bold;
    color: #333;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 2px solid #5FB878;
  }

  @media screen and (max-width: 767px) {
    .me-archive-container {
      flex-direction: column;
      gap: 20px;
    }

    .me-archive-sidebar {
      width: 100%;
      position: relative;
      top: auto;
    }

    .me-month-list {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
    }

    .me-month-item {
      width: calc(50% - 4px);
      justify-content: center;
      gap: 8px;
    }
  }

  @media screen and (min-width: 768px) and (max-width: 1024px) {
    .me-archive-sidebar {
      width: 180px;
    }
  }
</style>



